function splitWords(el) {
  if (!el) return;
  const text = el.textContent.trim();
  const cjk = /[一-鿿　-〿]/.test(text);
  const parts = cjk ? [text] : text.split(/\s+/);
  el.innerHTML = parts
    .map((w, i) => `<span class="word" style="--i:${i}">${w}</span>`)
    .join(' ');
}

